@Component("trade-handler")
@ProcessingGroup("trade-processing-group")
public class TradeEventHandler {
	
	// core constructor
	TradeEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTradeEvent
     */
    @EventHandler
    public void handle( CreateTradeEvent event) {
        entityManager.persist(new Trade(event.getTradeId(), event.getExecutedAt(), event.getQuantity(), event.getPrice(), event.getFees(), event.getSettlementDate(), event.getOrder(), event.getSecurity(), event.getInvestmentAccount()));
    }

    /*
     * @param	event UpdateTradeEvent
     */
    @EventHandler
    public Trade handle( UpdateTradeEvent event) {
    	entityManager.merge(new Trade(event.getTradeId(), event.getExecutedAt(), event.getQuantity(), event.getPrice(), event.getFees(), event.getSettlementDate(), event.getOrder(), event.getSecurity(), event.getInvestmentAccount()));
    }
    
    /*
     * @param	event DeleteTradeEvent
     */
    @EventHandler
    public void on( DeleteTradeEvent event) {
    	Trade entity = new Trade();
   
    	// ------------------------------------------
    	// apply the TradeId
    	// ------------------------------------------
    	entity.setTradeId( event.getTradeId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TradeRepository tradeEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TradeEventHandler.class.getName());

}
